import{_ as t,l as r,o as l,c as m,v as o,p as i,x as e,d as s,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"vmalloc","description":"","frontmatter":{"title":"vmalloc","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vmalloc.md","filePath":"cs/vmalloc.md","lastUpdated":1789023840000}'),p={name:"cs/vmalloc.md"};function h(v,a,E,_,u,A){const c=r("Mermaid");return l(),m("div",null,[a[1]||(a[1]=o('<h1 id="vmalloc" tabindex="-1">vmalloc <a class="header-anchor" href="#vmalloc" aria-label="Permalink to &quot;vmalloc&quot;">​</a></h1><div class="epigraph"><p>vmalloc 在内核虚空间找一段连续虚址，背后可以是不连续的页框，用来放下大缓冲而不要求 buddy 高阶成功。</p><footer>—— 据 Gorman 对 vmalloc 的说明；Linux vmalloc 文档</footer></div><p><a href="/cs/memory-hotplug">热插拔</a> 与 <a href="/cs/page-migration-compaction">compaction</a> 都在为<strong>物理连续</strong>奋斗。内核有时只需<strong>虚连续</strong>。缺口是 vmalloc：模块、大数组、<a href="/cs/xdp-ebpf">BPF</a> 映像。不是用户 <code>malloc</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>kmalloc</code> 要 physically contiguous，大了易失败。<a href="/cs/buddy-allocator">buddy</a> 高阶依赖反碎片。vmalloc：分配 N 个单页，装进内核页表一段连续 VA。缺口：TLB 效率差（多页）、持锁、不能用于某些 DMA（除非再映射）；<code>vmap</code> 已有页。本课不把 ioremap 的全部缓存属性写完，只点亲戚。</p><p><span class="marginnote">vmalloc 区在 64 位很大。原子上下文不能睡的路径不能 vmalloc。模块加载走这。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>vmalloc</code>：取虚区，alloc_page 循环，建立 pte。<code>vfree</code> 拆表还页。对照用户 mmap：都是虚连续物理可散；内核没有缺页处理同一套，通常预填。对照 <a href="/cs/thp">THP</a>：vmalloc 一般 4K。</p>',8)),(l(),i(n,null,{default:e(()=>[d(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%86%85%E6%A0%B8%E8%A6%81%E5%A4%A7%E7%BC%93%E5%86%B2%22%5D%20--%3E%20VA%5B%22%E8%BF%9E%E7%BB%AD%E5%86%85%E6%A0%B8%E8%99%9A%E5%9D%80%22%5D%0A%20%20VA%20--%3E%20PAGES%5B%22%E5%A4%9A%E5%BC%A0%E5%8F%AF%E8%83%BD%E4%B8%8D%E8%BF%9E%E7%BB%AD%E7%9A%84%E9%A1%B5%22%5D%0A%20%20PAGES%20--%3E%20PTE%5B%22%E5%86%85%E6%A0%B8%E9%A1%B5%E8%A1%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>vmalloc 用页表换「不必物理连续」，使内核在碎片化机器上仍能加载模块。代价是建立慢、访问可能更多 TLB miss。不要写成用户堆实现——那是后课 malloc。与 rmap：内核映射通常不走 anon_vma。</p><p>错误：把 vmalloc 地址传给只能 DMA 物理连续的设备会错，要用 bounce 或 <code>vmalloc_to_page</code> 逐页。</p><p>实现上：频繁 vmalloc/vfree 会打碎内核虚空间并伤 TLB。vmap 已有页用于模块或图形缓冲。原子上下文只能用预分配，不能睡着等页。 读法上只引用<a href="/cs/memory-hotplug">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>vmalloc</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 vmap 栈的 hardened 配置全文。不保证实时延迟。下一课对照：直接映射与高端内存为何存在。</p><p>版本字段会变，课序钉的是机制对象「vmalloc」，不是某一主线内核的结构体名。 后课默认：内核可用 vmalloc 得虚连续。线性映射与 HIGHMEM，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>vmalloc：虚连续、物理可散。</li><li>kmalloc：物理连续，大分配易失败。</li><li>直接映射与 highmem 是下一课。</li><li>出处：Gorman；Linux mm/vmalloc.c 文档；<em>ULK</em>。</li></ul>',11))])}const T=t(p,[["render",h]]);export{B as __pageData,T as default};
